import"./chunk-7CGTOI24.js";var e={slug:"series-baseadas-em-games-ranking",title:"As 6 melhores s\xE9ries baseadas em games, segundo a reda\xE7\xE3o",dek:"De Arcane a Twisted Metal, ranqueamos as adapta\xE7\xF5es de videogame para a TV que realmente valem a maratona. Opini\xE3o da casa, dados do TMDB.",section:"series",kind:"lista",tags:["Adapta\xE7\xE3o","Netflix","HBO","Prime Video","Anima\xE7\xE3o"],date:"2026-11-01",hero:{ref:"tv:100088",pick:0,alt:"Joel e Ellie em cena de The Last of Us"},body:[{p:"Por muito tempo, \u201Cadapta\xE7\xE3o de game\u201D foi um alerta. A TV mudou isso. Com mais tempo para desenvolver personagens, as s\xE9ries conseguiram o que o cinema raramente alcan\xE7ava: respeitar o material original e funcionar para quem nunca encostou no controle. Este \xE9 o nosso ranking, puramente opinativo."},{entry:"tv:94605",title:"Arcane",text:["Anima\xE7\xE3o de n\xEDvel cinematogr\xE1fico, uma hist\xF3ria fechada em duas temporadas e personagens que voc\xEA n\xE3o esquece. N\xE3o precisa conhecer *League of Legends*. Leia a nossa [review completa](/artigo/review-arcane-a-melhor-adaptacao-de-game)."]},{entry:"tv:100088",title:"The Last of Us",text:["Craig Mazin e Neil Druckmann, cocriador do jogo, levaram a jornada de Joel e Ellie para a HBO com Pedro Pascal e Bella Ramsey. A primeira temporada \xE9 uma das melhores estreias de drama da d\xE9cada, e o terceiro epis\xF3dio virou refer\xEAncia por si s\xF3."]},{entry:"tv:106379",title:"Fallout",text:["Humor \xE1cido, viol\xEAncia estilizada e um entendimento raro do tom dos jogos. Walton Goggins como o Ghoul \xE9 o tipo de escala\xE7\xE3o que define uma s\xE9rie. Veja o nosso [guia para ir da s\xE9rie aos jogos](/artigo/fallout-do-jogo-a-serie-guia)."]},{entry:"tv:71024",title:"Castlevania",text:["A s\xE9rie de Warren Ellis provou que a Netflix podia fazer anima\xE7\xE3o adulta de fantasia sombria. S\xE3o quatro temporadas com Trevor Belmont, Sypha e Alucard, e uma derivada, *Castlevania: Noturno*."]},{entry:"tv:105248",title:"Cyberpunk: Mercen\xE1rios",text:["O Studio Trigger transformou Night City em uma trag\xE9dia curta e intensa sobre David Martinez. A primeira temporada, de 2022, \xE9 perfeita do come\xE7o ao fim, e a s\xE9rie ganhou uma segunda temporada que terminou em outubro de 2026, segundo o TMDB."]},{entry:"tv:133748",title:"Twisted Metal",text:["A menos s\xE9ria da lista e, por isso mesmo, divertida. Anthony Mackie \xE9 um entregador em uma Am\xE9rica p\xF3s-apocal\xEDptica, e o palha\xE7o Sweet Tooth rouba todas as cenas. Duas temporadas no Peacock."]},{box:"Ficaram de fora s\xE9ries baseadas em livros que tamb\xE9m viraram jogos, como The Witcher. O crit\xE9rio \xE9 ter o game como fonte principal.",title:"Crit\xE9rio"}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{},tv:{71024:{id:71024,name:"Castlevania",original:"Castlevania",overview:"Um ca\xE7ador de vampiros luta para salvar uma cidade sitiada por um ex\xE9rcito de criaturas controladas pelo pr\xF3prio Dr\xE1cula.",poster:"/WzFHnJY44uDERER0xi1jOdoafT.jpg",backdrops:["/jLE5bsPA9xOKzBWOaOmKbp1DWQS.jpg","/4QuQIFQXw6NclP4lGPqmXmHAWdH.jpg","/w7QjHvInR5JZphFWWXp61GtwU08.jpg","/9AEdLZqPeuKGfMtvdIYVsNI7ig2.jpg","/3CWVK7qFTtdtpT0Daw9Zj8DVFpx.jpg"],genres:["Anima\xE7\xE3o","Sci-Fi & Fantasy","Drama"],cert:"16",creators:["Warren Ellis"],cast:[{name:"Richard Armitage",role:"Trevor Belmont (voz)"},{name:"James Callis",role:"Adrian Tepes / Alucard (voz)"},{name:"Alejandra Reynoso",role:"Sypha Belnades (voz)"},{name:"Adetokumboh M'Cormack",role:"Isaac (voz)"},{name:"Jaime Murray",role:"Carmilla (voz)"},{name:"Bill Nighy",role:"Saint Germain (voz)"}],networks:["Netflix"],first:"2017-07-07",last:"2021-05-13",status:"Encerrada",seasons:4,episodes:32,next:null,country:"US"},94605:{id:94605,name:"Arcane",original:"Arcane",overview:"Em meio ao conflito entre as cidades-g\xEAmeas de Piltover e Zaun, duas irm\xE3s lutam em lados opostos de uma guerra entre tecnologias m\xE1gicas e convic\xE7\xF5es incompat\xEDveis.",poster:"/m3Tzf6k537PnhOEwaSRNCSxedLS.jpg",backdrops:["/5cvnxEHT3e39DvT6ARw4GNCFrB0.jpg","/q8eejQcg1bAqImEV8jh8RtBD4uH.jpg","/4ACkRHJCMXdNUUBem3Z0n1CclKf.jpg","/3WrZvh1spUdyEsgukJxAuCKHAQb.jpg","/sYXLeu5usz6yEz0k00FYvtEdodD.jpg"],genres:["Anima\xE7\xE3o","Action & Adventure","Sci-Fi & Fantasy"],cert:"16",creators:["Christian Linke","Alex Yee"],cast:[{name:"Hailee Steinfeld",role:"Vi (voz)"},{name:"Ella Purnell",role:"Jinx (voz)"},{name:"Kevin Alejandro",role:"Jayce (voz)"},{name:"Toks Olagundoye",role:"Mel Medarda (voz)"},{name:"Harry Lloyd",role:"Viktor (voz)"},{name:"Katie Leung",role:"Caitlyn (voz)"}],networks:["Netflix"],first:"2021-11-06",last:"2024-11-23",status:"Encerrada",seasons:2,episodes:18,next:null,country:"US"},100088:{id:100088,name:"The Last of Us",original:"The Last of Us",overview:"Situado duas d\xE9cadas ap\xF3s a implos\xE3o de nossa sociedade, o drama seguir\xE1 Joel, um sobrevivente dif\xEDcil, que \xE9 contratado para contrabandear uma garota de 14 anos chamada Ellie para fora de uma zona de quarentena opressiva. O que come\xE7a como um pequeno trabalho logo se torna uma jornada brutal e de partir o cora\xE7\xE3o, j\xE1 que os dois precisam atravessar os Estados Unidos e dependem um do outro para sobreviver.",poster:"/qWo5TP7mBijoZrfxBJkUMctkBt0.jpg",backdrops:["/lY2DhbA7Hy44fAKddr06UrXWWaQ.jpg","/uDgy6hyPd82kOHh6I95FLtLnj6p.jpg","/2RSbYPDkNd3hkGp4VWpTFalU9z7.jpg","/acevLdSl5I2MK5RYAm7gwAndt1w.jpg","/7dowXHcFccjmxf0YZYxDFkfVq65.jpg"],genres:["Drama"],cert:"16",creators:["Neil Druckmann","Craig Mazin"],cast:[{name:"Bella Ramsey",role:"Ellie Williams"},{name:"Pedro Pascal",role:"Joel Miller"},{name:"Gabriel Luna",role:"Tommy Miller"},{name:"Isabela Merced",role:"Dina"},{name:"Young Mazino",role:"Jesse"},{name:"Rutina Wesley",role:"Maria"}],networks:["HBO"],first:"2023-01-15",last:"2025-05-25",status:"Em produ\xE7\xE3o",seasons:2,episodes:16,next:null,country:"US"},105248:{id:105248,name:"Cyberpunk: Mercen\xE1rios",original:"Cyberpunk: Edgerunners",overview:"Para sobreviver em uma realidade dist\xF3pica na qual a corrup\xE7\xE3o e os implantes cibern\xE9ticos controlam tudo, um jovem talentoso e impulsivo decide se tornar um mercen\xE1rio.",poster:"/nWvAY8yHE873adMws83XqBPf7W2.jpg",backdrops:["/bknKZO7DWVYKeByuJMnGI46PFZg.jpg","/obzl1uYiC8gevu2YZIifw42hRt5.jpg","/qHYdWT5NYqtlYpvQKOqZaq2mTrk.jpg","/gLlemMoIN4vbKvZvOWInWGxeQNL.jpg","/3UbHGmu9vIMSC5uNfnGt7DjetqT.jpg"],genres:["Anima\xE7\xE3o","Action & Adventure","Sci-Fi & Fantasy"],cert:"16",creators:["Rafa\u0142 Jaki","Bartosz Sztybor"],cast:[{name:"KENN",role:"David Martinez (voz)"},{name:"Koki Uchiyama",role:"D (voz)"},{name:"Akari Kito",role:"Talia (voz)"},{name:"Kentaro Tone",role:"Weak (voz)"},{name:"Kento Shiraishi",role:"Animal (voz)"},{name:"Aoi Yuki",role:"Lucy (voz)"}],networks:["Netflix"],first:"2022-09-13",last:"2026-10-20",status:"Em produ\xE7\xE3o",seasons:2,episodes:20,next:null,country:"JP"},106379:{id:106379,name:"Fallout",original:"Fallout",overview:"Baseada em uma das maiores s\xE9ries de videogame de todos os tempos, Fallout \xE9 a hist\xF3ria de quem tem e de quem n\xE3o tem, em um mundo onde n\xE3o existe quase nada para se ter. 200 anos ap\xF3s o apocalipse, uma habitante pac\xEDfica de um agrad\xE1vel ref\xFAgio \xE9 for\xE7ada a se aventurar na superf\xEDcie e fica chocada quando descobre a terra devastada que a espera.",poster:"/tQRX6GbYooU7kUaarKf5YXDTONy.jpg",backdrops:["/coaPCIqQBPUZsOnJcWZxhaORcDT.jpg","/cIgHBLTMbcIkS0yvIrUUVVKLdOz.jpg","/4d0tMAk49gqbVwgvtQjCriBwyb8.jpg","/mOc49WDMEr3V3cpjRkhHCTaJxd6.jpg","/bFvomL5Bui3rxSBROlKgYnTaQth.jpg"],genres:["Action & Adventure","Sci-Fi & Fantasy","Drama"],cert:"18",creators:["Graham Wagner","Geneva Robertson-Dworet"],cast:[{name:"Ella Purnell",role:"Lucy MacLean"},{name:"Aaron Moten",role:"Maximus"},{name:"Mois\xE9s Arias",role:"Norm MacLean"},{name:"Walton Goggins",role:"The Ghoul / Cooper Howard"},{name:"Frances Turner",role:"Barb Howard"},{name:"Kyle MacLachlan",role:"Overseer Hank MacLean"}],networks:["Prime Video"],first:"2024-04-10",last:"2026-02-03",status:"Em produ\xE7\xE3o",seasons:2,episodes:16,next:null,country:"US"},133748:{id:133748,name:"Twisted Metal",original:"Twisted Metal",overview:"Um forasteiro deve atravessar uma terra arrasada p\xF3s-apocal\xEDptica para entregar um pacote misterioso em busca da promessa de uma vida melhor.",poster:"/zMwMClR9y7RBeVWMEmNn8LwUJHz.jpg",backdrops:["/6wLJiFwmuZNvTiE9aqFqx4dDcWh.jpg","/6XQQgp86rl6TaOpzxSUF5OHizib.jpg","/1fufhVQmyv5VMMapmF6MPJ7WWfe.jpg","/uR9B8id68XcYthaOKtLGFwp7qkW.jpg","/n4PWyfNiuQc3DnBV5u8A6p2xPU4.jpg"],genres:["Action & Adventure","Com\xE9dia"],cert:"16",creators:["Rhett Reese","Paul Wernick","Michael Jonathan Smith"],cast:[{name:"Anthony Mackie",role:"John Doe"},{name:"Stephanie Beatriz",role:"Quiet"},{name:"Nuufolau Joel Seanoa",role:"Sweet Tooth"},{name:"Will Arnett",role:"Sweet Tooth (voz)"},{name:"Mike Mitchell",role:"Stu"},{name:"Tahj Vaughans",role:"Mike"}],networks:["Peacock"],first:"2023-07-27",last:"2025-08-28",status:"Em produ\xE7\xE3o",seasons:2,episodes:22,next:null,country:"US"}}};export{o as media,e as post};
